export type CrackstoneMode = 'PATROL' | 'INVESTIGATE' | 'CHASE' | 'ATTACK' | 'SEARCH' | 'RETURN';
export type CrackstoneDetectVia = 'sight' | 'proximity' | 'scan';
export type CrackstoneModeReason = 'saw_player' | 'sensed_player' | 'scan_hit' | 'lost_sight' | 'leash' | 'reached_target' | 'gave_up' | 'search_timeout' | 'returned' | 'curse_cast' | 'curse_done' | 'curse_missed' | 'stunned' | 'lured' | 'deferred';

export interface CrackstoneRuntime {
  mode: CrackstoneMode;
  modeT: number;
  x: number; z: number; yaw: number; speed: number;
  suspicion: number; // 0..1
  canSeePlayer: boolean;
  lastKnown: Vec2 | null;
  target: Vec2 | null;
  path: Vec2[];
  stunnedUntil: number; slowedUntil: number; slowMult: number; distractedUntil: number;
  /** PUBLIC telegraph: supernatural scan pending ('warning', he stands still, ring grows) or just fired ('pulse'). */
  scan: { phase: 'warning' | 'pulse'; startedAt: number; pulseAt: number; radiusM: number } | null;
  /** PUBLIC telegraph: curse circle on the ground; lands at `landsAt` on a player still inside it (with LOS). */
  curse: { x: number; z: number; radiusM: number; startedAt: number; landsAt: number } | null;
}

/** Slurp (Isaac Night's zombie form): sight + proximity stalker (FINAL_CONTRACT Slurp). */
export type SlurpMode = 'WANDER' | 'INVESTIGATE' | 'CHASE' | 'ATTACK' | 'SEARCH' | 'LEAVE';
export interface SlurpRuntime {
  active: boolean; // false = despawned / not yet spawned
  mode: SlurpMode;
  modeT: number;
  x: number; z: number; yaw: number; speed: number;
  suspicion: number;
  canSeePlayer: boolean;
  lastKnown: Vec2 | null;
  target: Vec2 | null;
  path: Vec2[];
  stunnedUntil: number; slowedUntil: number; slowMult: number; distractedUntil: number;
  attacking: boolean; // short lunge / grab window
}

export type RunStatus = 'tutorial' | 'playing' | 'accusing' | 'finished' | 'dnf';
export type DnfReason = 'second_catch' | 'hp_depleted';

export interface AbilityStatus { ready: boolean; cooldownLeftS: number; activeLeftS: number }

/** What is currently in effect, for the renderer and HUD (derived from active F/Q effects). */
export interface ActiveEffects {
  revealedClues: ClueId[]; // uncollected clues currently highlighted
  revealEgg: boolean; // egg highlighted (reveal effects also show a resting/dropped egg)
  revealHazards: boolean; // walls/cover/hiding spots outlined near the player
  premonitionPath: Vec2[] | null; // the Hyde's predicted path (Morticia)
  scentTrail: Vec2[] | null; // path toward the nearest uncollected objective (Enid's Wolf Shift)
  speedBoost: boolean;
  lurePoint: Vec2 | null; // a decoy the Hyde is investigating
  hydeDistracted: boolean;
  hydeStunned: boolean;
  hydePetrified: boolean; // stun applied by a gaze/pin effect (renderer shows stone/pinned look)
  hydeSlowed: boolean;
  blockGrab: boolean; // next grab (or Crackstone curse) blocked (a grab's catch still counts)
  eggShield: boolean;
  switchPowered: boolean;
  /** Crackstone counterparts (all false / null without a Crackstone). */
  crackstoneDistracted: boolean;
  crackstoneStunned: boolean;
  crackstonePetrified: boolean;
  crackstoneSlowed: boolean;
  /** Crackstone's predicted path (premonition), when he is in range. */
  crackstonePremonitionPath: Vec2[] | null;
  /** A reveal effect currently shows enemies (Hyde / Crackstone) within `enemyRevealRangeM` (0 = anywhere). */
  enemiesRevealed: boolean;
  enemyRevealRangeM: number;
  /** Player slowed by a landed curse (movement × tuning crackstone.curseSlowMult). */
  cursed: boolean;
  last: { key: 'F' | 'Q'; abilityId: string; kinds: AbilityEffectKind[]; t: number } | null;
}

/** Per-frame input, built by the app from keyboard + pointer-lock mouse. */
export interface MysteryInput {
  moveX: number; // −1 left … 1 right (A/D)
  moveZ: number; // −1 back … 1 forward (S/W)
  lookYawDelta: number; // radians this frame (mouse X)
  lookPitchDelta: number; // radians (mouse Y)
  sprint: boolean; // Shift held
  crouch: boolean; // crouch state requested this frame (the app resolves hold vs toggle)
  interact: boolean; // E (edge)
  interactHeld?: boolean; // E currently held (hold 0.8 s with the egg and nothing else in reach = set it down)
  power: boolean; // F (edge)
  move: boolean; // Q (edge)
  hint: boolean; // V (edge)
}

// ----------------------------------------------------------------------------------------------------- events

export type NoiseSource = 'footstep' | 'egg_drop' | 'ability' | 'interact' | 'impact' | 'decoy' | 'hazard';
export type GameEvent =
  | { type: 'noise'; source: NoiseSource; x: number; z: number; loudness: number; radiusM: number }
  | { type: 'stance'; stance: Stance }
  | { type: 'room_enter'; roomId: RoomId }
  | { type: 'hyde_mode'; from: HydeMode; to: HydeMode; reason: 'heard_noise' | 'saw_player' | 'lost_sight' | 'search_timeout' | 'cooldown_done' | 'reached_target' | 'stunned' | 'lured' | 'grabbed' | 'gave_up' }
  | { type: 'hyde_heard'; source: NoiseSource; loudness: number; distanceM: number; occluded: boolean }
  | { type: 'hyde_sighted'; distanceM: number }
  | { type: 'hyde_lost' }
  | { type: 'catch'; catchNumber: 1 | 2; hpLost: number; eggSecurityLost: number; blocked: boolean }
  | { type: 'clue_search_start'; clueId: ClueId }
  | { type: 'clue_found'; clueId: ClueId; cluesFound: number }
  | { type: 'egg_pickup' }
  | { type: 'egg_drop'; reason: 'manual' | 'impact' | 'grab'; security: number }
  | { type: 'egg_damage'; amount: number; cause: 'grab' | 'impact' | 'drop'; security: number }
  | { type: 'egg_delivered'; tier: EggTier; points: number; security: number }
  | { type: 'ability_used'; key: 'F' | 'Q'; abilityId: string; kinds: AbilityEffectKind[]; success: boolean; detail: string }
  | { type: 'ability_denied'; key: 'F' | 'Q'; reason: 'cooldown' | 'no_target' }
  | { type: 'hint_requested'; level?: 1 | 2 | 3 } // final: an explicit Ask-Weems hint (scored -50); level = Weems' ladder step
  // ---- overhaul (telemetry only; not rule events)
  | { type: 'hyde_emerged'; spawnId: string; x: number; z: number }
  | { type: 'site_checked'; site: 'clue' | 'egg'; siteId: string; found: boolean }
  | { type: 'trace_found'; sourceId: string; siteId: string }
  | { type: 'examined'; examineId: string }
  | { type: 'passage_opened'; passageId: string }
  | { type: 'hazard_triggered'; hazardId: string }
  // ---- Joseph Crackstone (ENEMY_CONTRACT; telemetry + rule events)
  | { type: 'crackstone_mode'; from: CrackstoneMode; to: CrackstoneMode; reason: CrackstoneModeReason }
  | { type: 'crackstone_sighted'; via: CrackstoneDetectVia; distanceM: number }
  | { type: 'crackstone_lost' }
  | { type: 'crackstone_scan'; phase: 'warning' | 'pulse'; radiusM: number; hit: boolean }
  | { type: 'curse'; phase: 'cast' | 'hit' | 'miss'; hpLost: number; blocked: boolean }
  // ---- final (FINAL_CONTRACT): encounter director, Slurp, cabinets, scoring evidence
  | { type: 'enemy_spawned'; enemy: EnemyId; spawnId: string; x: number; z: number }
  | { type: 'enemy_despawned'; enemy: EnemyId; reason: 'far' | 'cycle_done' | 'encounter_resolved' }
  /** RULE event (scoring): an enemy started hunting the player (any detection removes the no-detection bonus). */
  | { type: 'enemy_detected'; enemy: EnemyId; via: 'sight' | 'sound' | 'proximity' | 'scan' | 'witnessed_hide' }
  /** RULE event (scoring): the player took a monster hit (Hyde grab, curse hit, Slurp attack); blocked hits still count. */
  | { type: 'enemy_hit'; enemy: EnemyId; hpLost: number; blocked: boolean }
  | { type: 'slurp_mode'; from: SlurpMode; to: SlurpMode; reason: 'saw_player' | 'sensed_player' | 'heard_noise' | 'lost_sight' | 'search_timeout' | 'reached_target' | 'attack_done' | 'stunned' | 'lured' | 'leash' | 'gave_up' | 'deferred' }
  | { type: 'cabinet'; spotId: string; action: 'enter' | 'close' | 'open' | 'exit' | 'pulled_out'; loud: boolean }
  | { type: 'accusation'; suspectId: SuspectId | null; correct: boolean; cluesFound: number; evidence: string[]; deductionCorrect: boolean }
  | { type: 'finish'; verdict: Verdict; score: number }
  | { type: 'dnf'; reason: DnfReason; by?: EnemyId | null };

/** Every event carries the active sim time and a per-run monotonic sequence number (Supabase uses (session, seq)). */
export type StampedEvent = GameEvent & { t: number; seq: number };

/** Sparse 1 Hz snapshot used by analytics (never sent per frame). Only information available at time t. */
export interface StateSnapshot {
  t: number;
  roomId: RoomId | null;
  stance: Stance;
  speed: number;
  hp: number;
  catches: number;
  hidden: boolean;
  eggState: EggState;
  eggSecurity: number;
  cluesFound: number;
  hydeMode: HydeMode;
  hydeDistanceM: number;
  hydeOccluded: boolean; // a wall blocks the straight line between player and Hyde
  hydeSuspicion: number;
  recentNoise: number; // max own loudness in the last 3 s
  powerReady: boolean;
  moveReady: boolean;
  objective: Objective;
  /** Overhaul: the Hyde has emerged (before that it is absent). */
  hydeEmerged: boolean;
  /** Overhaul: the player can currently see the Hyde (LOS within sight.playerSeesHydeM). */
  hydeVisible: boolean;
  /** Enemy contract: Joseph Crackstone is in this case (false = no second enemy; the fields below are then defaults). */
  crackstonePresent: boolean;
  crackstoneMode: CrackstoneMode;
  /** Distance to Crackstone (m); HYDE_ABSENT_DISTANCE_M (999) without a Crackstone. */
  crackstoneDistanceM: number;
  crackstoneOccluded: boolean;
  crackstoneVisible: boolean;
  crackstoneSuspicion: number;
  /** Final (optional until filled): director + Slurp + cabinet state. */
  hydeActive?: boolean;
  crackstoneActive?: boolean;
  slurpPresent?: boolean;
  slurpActive?: boolean;
  slurpMode?: SlurpMode;
  slurpDistanceM?: number;
  slurpVisible?: boolean;
  inCabinet?: 'open' | 'closed' | null;
}

/** StateSnapshot fields when there is no Crackstone (fixtures, older dataset rows). 999 = HYDE_ABSENT_DISTANCE_M. */
export const CRACKSTONE_ABSENT_SNAPSHOT: Pick<StateSnapshot,
  'crackstonePresent' | 'crackstoneMode' | 'crackstoneDistanceM' | 'crackstoneOccluded' | 'crackstoneVisible' | 'crackstoneSuspicion'> = {
  crackstonePresent: false, crackstoneMode: 'PATROL', crackstoneDistanceM: 999, crackstoneOccluded: true, crackstoneVisible: false,
  crackstoneSuspicion: 0,
};

/** ActiveEffects fields when nothing affects Crackstone / no enemy reveal / no curse. */
export const CRACKSTONE_NO_EFFECTS: Pick<ActiveEffects,
  'crackstoneDistracted' | 'crackstoneStunned' | 'crackstonePetrified' | 'crackstoneSlowed' | 'crackstonePremonitionPath'
  | 'enemiesRevealed' | 'enemyRevealRangeM' | 'cursed'> = {
  crackstoneDistracted: false, crackstoneStunned: false, crackstonePetrified: false, crackstoneSlowed: false,
  crackstonePremonitionPath: null, enemiesRevealed: false, enemyRevealRangeM: 0, cursed: false,
};

export type Objective = 'find_clues' | 'find_egg' | 'retrieve_egg' | 'deliver_egg' | 'accuse' | 'done';

export interface RunResult {
  rulesVersion: MysteryRulesVersion;
  caseId: CaseId;
  caseVersion: number;
  outcome: 'finished' | 'dnf';
  dnfReason: DnfReason | null;
  verdict: Verdict;
  accused: SuspectId | null;
  correct: boolean;
  /** Evidence ids cited with the accusation (clues and/or case-file notes). */
  evidence: string[];
  /** The cited evidence is exactly the case's supporting evidence. */
  deductionCorrect: boolean;
  cluesFound: ClueId[];
  eggTier: Exclude<EggTier, 'none'>;
  eggPoints: number; // delivered whole points (0 when not delivered)
  eggSecurity: number;
  activeTimeS: number; // 1 dp
  score: number | null; // (points × 100) − activeTimeS, 1 dp; null for DNF
  catches: number;
  hp: number;
  duo: Duo;
  /** Final scoring evidence (mystery-v4): counted from rule events; the server recomputes all of them. */
  hintsUsed?: number;
  detections?: number;
  hits?: number;
  /** Which monster defeated the player (DNF only). */
  defeatedBy?: EnemyId | null;
  scoreBreakdown?: ScoreBreakdown | null;
}

/** mystery-v4 score components (finishers only). total = max(0, sum of the signed parts). */
export interface ScoreBreakdown {
  delivery: number; // +1000
  accusation: number; // +300 correct culprit
  clues: number; // +100 x required clues found (max 300)
  noDetection: number; // +150 when detections = 0
  noHints: number; // +150 when hintsUsed = 0
  timeBonus: number; // max(0, 300 - floor(activeTimeS))
  hintPenalty: number; // -50 x hintsUsed (<= 0)
  hitPenalty: number; // -75 x hits (<= 0)
  total: number;
}

export interface StationContext { stationId: StationId | null; sessionId: string; offer: DuoOffer }
